
import { useState, useRef } from 'react';

type PostType = 'diary' | 'mycar' | 'garage' | 'touring';

interface PostModalProps {
  isOpen: boolean;
  onClose: () => void;
  postType: PostType;
  onSubmit: (data: Record<string, string | string[]>) => void;
}

const tabLabels: Record<PostType, string> = {
  diary: '日記を投稿',
  mycar: 'Myカーを登録',
  garage: 'ガレージ写真を投稿',
  touring: 'ツーリングを募集',
};

const categoryOptions = [
  'メンテナンス', 'ドライブ', 'カスタム', 'エコドライブ',
  'サーキット', 'アウトドア', 'DIY', 'レストア', 'その他',
];

const makerOptions = [
  'トヨタ', 'ホンダ', '日産', 'マツダ', 'スバル',
  'スズキ', 'ダイハツ', '三菱', 'レクサス', 'BMW', 'メルセデス・ベンツ', 'その他',
];

export default function PostModal({ isOpen, onClose, postType, onSubmit }: PostModalProps) {
  const [title, setTitle] = useState('');
  const [body, setBody] = useState('');
  const [category, setCategory] = useState('');
  const [maker, setMaker] = useState('');
  const [model, setModel] = useState('');
  const [year, setYear] = useState('');
  const [cc, setCC] = useState('');
  const [customTags, setCustomTags] = useState('');
  const [date, setDate] = useState('');
  const [location, setLocation] = useState('');
  const [maxParticipants, setMaxParticipants] = useState('');
  const [previewImages, setPreviewImages] = useState<string[]>([]);
  const [submitting, setSubmitting] = useState(false);
  const [success, setSuccess] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  if (!isOpen) return null;

  const handleImageSelect = () => {
    fileInputRef.current?.click();
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files) return;
    const newImages: string[] = [];
    Array.from(files).forEach((file) => {
      const reader = new FileReader();
      reader.onload = (ev) => {
        if (ev.target?.result) {
          newImages.push(ev.target.result as string);
          if (newImages.length === files.length) {
            setPreviewImages((prev) => [...prev, ...newImages].slice(0, 5));
          }
        }
      };
      reader.readAsDataURL(file);
    });
  };

  const removeImage = (index: number) => {
    setPreviewImages((prev) => prev.filter((_, i) => i !== index));
  };

  const resetForm = () => {
    setTitle('');
    setBody('');
    setCategory('');
    setMaker('');
    setModel('');
    setYear('');
    setCC('');
    setCustomTags('');
    setDate('');
    setLocation('');
    setMaxParticipants('');
    setPreviewImages([]);
    setSubmitting(false);
    setSuccess(false);
  };

  const handleClose = () => {
    resetForm();
    onClose();
  };

  const canSubmit = () => {
    if (!title.trim()) return false;
    if (postType === 'diary' && !category) return false;
    if (postType === 'mycar' && (!maker || !model)) return false;
    if (postType === 'touring' && (!date || !location)) return false;
    return true;
  };

  const handleSubmit = () => {
    if (!canSubmit()) return;
    setSubmitting(true);
    setTimeout(() => {
      onSubmit({
        type: postType,
        title,
        body,
        category,
        maker,
        model,
        year,
        cc,
        customTags: customTags.split(',').map((t) => t.trim()).filter(Boolean),
        date,
        location,
        maxParticipants,
        images: previewImages,
      });
      setSubmitting(false);
      setSuccess(true);
      setTimeout(() => {
        handleClose();
      }, 1500);
    }, 800);
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center">
      <div className="absolute inset-0 bg-black/50" onClick={handleClose} />
      <div className="relative bg-white rounded-lg w-full max-w-2xl max-h-[90vh] overflow-y-auto mx-4 shadow-2xl">
        {/* 成功メッセージ */}
        {success && (
          <div className="absolute inset-0 z-10 bg-white/95 rounded-lg flex flex-col items-center justify-center">
            <div className="w-16 h-16 flex items-center justify-center bg-green-100 rounded-full mb-4">
              <i className="ri-check-line text-3xl text-green-600"></i>
            </div>
            <p className="text-lg font-bold text-gray-900">投稿が完了しました！</p>
            <p className="text-sm text-gray-500 mt-1">コミュニティに公開されました</p>
          </div>
        )}

        {/* ヘッダー */}
        <div className="flex items-center justify-between px-6 py-4 border-b border-gray-200">
          <h2 className="text-lg font-bold text-gray-900">{tabLabels[postType]}</h2>
          <button
            onClick={handleClose}
            className="w-8 h-8 flex items-center justify-center rounded-full hover:bg-gray-100 transition-colors cursor-pointer"
          >
            <i className="ri-close-line text-xl text-gray-500"></i>
          </button>
        </div>

        {/* フォーム */}
        <div className="px-6 py-5 space-y-5">
          {/* 共通: タイトル */}
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1.5">
              タイトル <span className="text-red-500">*</span>
            </label>
            <input
              type="text"
              value={title}
              onChange={(e) => setTitle(e.target.value)}
              placeholder={
                postType === 'diary' ? '日記のタイトルを入力' :
                postType === 'mycar' ? '愛車の紹介タイトル' :
                postType === 'garage' ? '写真のタイトル' :
                'ツーリングのタイトル'
              }
              className="w-full border border-gray-300 rounded-lg px-4 py-2.5 text-sm focus:outline-none focus:border-teal-500 focus:ring-1 focus:ring-teal-500"
            />
          </div>

          {/* 日記: カテゴリ */}
          {postType === 'diary' && (
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1.5">
                カテゴリ <span className="text-red-500">*</span>
              </label>
              <div className="flex flex-wrap gap-2">
                {categoryOptions.map((cat) => (
                  <button
                    key={cat}
                    onClick={() => setCategory(cat)}
                    className={`px-3 py-1.5 rounded-full text-xs font-medium whitespace-nowrap transition-colors cursor-pointer ${
                      category === cat
                        ? 'bg-teal-500 text-white'
                        : 'bg-gray-100 text-gray-600 hover:bg-gray-200'
                    }`}
                  >
                    {cat}
                  </button>
                ))}
              </div>
            </div>
          )}

          {/* Myカー: 車両情報 */}
          {postType === 'mycar' && (
            <div className="space-y-4">
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1.5">
                    メーカー <span className="text-red-500">*</span>
                  </label>
                  <select
                    value={maker}
                    onChange={(e) => setMaker(e.target.value)}
                    className="w-full border border-gray-300 rounded-lg px-4 py-2.5 text-sm focus:outline-none focus:border-teal-500 focus:ring-1 focus:ring-teal-500 cursor-pointer"
                  >
                    <option value="">選択してください</option>
                    {makerOptions.map((m) => (
                      <option key={m} value={m}>{m}</option>
                    ))}
                  </select>
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1.5">
                    車種名 <span className="text-red-500">*</span>
                  </label>
                  <input
                    type="text"
                    value={model}
                    onChange={(e) => setModel(e.target.value)}
                    placeholder="例: GR86"
                    className="w-full border border-gray-300 rounded-lg px-4 py-2.5 text-sm focus:outline-none focus:border-teal-500 focus:ring-1 focus:ring-teal-500"
                  />
                </div>
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1.5">年式</label>
                  <input
                    type="number"
                    value={year}
                    onChange={(e) => setYear(e.target.value)}
                    placeholder="例: 2024"
                    className="w-full border border-gray-300 rounded-lg px-4 py-2.5 text-sm focus:outline-none focus:border-teal-500 focus:ring-1 focus:ring-teal-500"
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1.5">排気量 (cc)</label>
                  <input
                    type="number"
                    value={cc}
                    onChange={(e) => setCC(e.target.value)}
                    placeholder="例: 2400"
                    className="w-full border border-gray-300 rounded-lg px-4 py-2.5 text-sm focus:outline-none focus:border-teal-500 focus:ring-1 focus:ring-teal-500"
                  />
                </div>
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1.5">カスタム内容（カンマ区切り）</label>
                <input
                  type="text"
                  value={customTags}
                  onChange={(e) => setCustomTags(e.target.value)}
                  placeholder="例: マフラー交換, 車高調, ホイール"
                  className="w-full border border-gray-300 rounded-lg px-4 py-2.5 text-sm focus:outline-none focus:border-teal-500 focus:ring-1 focus:ring-teal-500"
                />
              </div>
            </div>
          )}

          {/* ツーリング: イベント情報 */}
          {postType === 'touring' && (
            <div className="space-y-4">
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1.5">
                    開催日 <span className="text-red-500">*</span>
                  </label>
                  <input
                    type="date"
                    value={date}
                    onChange={(e) => setDate(e.target.value)}
                    className="w-full border border-gray-300 rounded-lg px-4 py-2.5 text-sm focus:outline-none focus:border-teal-500 focus:ring-1 focus:ring-teal-500 cursor-pointer"
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1.5">
                    募集人数
                  </label>
                  <input
                    type="number"
                    value={maxParticipants}
                    onChange={(e) => setMaxParticipants(e.target.value)}
                    placeholder="例: 20"
                    className="w-full border border-gray-300 rounded-lg px-4 py-2.5 text-sm focus:outline-none focus:border-teal-500 focus:ring-1 focus:ring-teal-500"
                  />
                </div>
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1.5">
                  開催場所 <span className="text-red-500">*</span>
                </label>
                <input
                  type="text"
                  value={location}
                  onChange={(e) => setLocation(e.target.value)}
                  placeholder="例: 山梨県・富士五湖エリア"
                  className="w-full border border-gray-300 rounded-lg px-4 py-2.5 text-sm focus:outline-none focus:border-teal-500 focus:ring-1 focus:ring-teal-500"
                />
              </div>
            </div>
          )}

          {/* 共通: 本文 */}
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1.5">
              {postType === 'touring' ? '詳細・説明' : '本文'}
            </label>
            <textarea
              value={body}
              onChange={(e) => {
                if (e.target.value.length <= 500) setBody(e.target.value);
              }}
              placeholder={
                postType === 'diary' ? '今日のカーライフについて書いてみましょう...' :
                postType === 'mycar' ? '愛車の紹介やこだわりポイントを書いてみましょう...' :
                postType === 'garage' ? 'カスタムの詳細やこだわりを書いてみましょう...' :
                'ツーリングの詳細やルート、集合場所などを書いてみましょう...'
              }
              rows={4}
              className="w-full border border-gray-300 rounded-lg px-4 py-2.5 text-sm focus:outline-none focus:border-teal-500 focus:ring-1 focus:ring-teal-500 resize-none"
            />
            <p className="text-xs text-gray-400 text-right mt-1">{body.length}/500</p>
          </div>

          {/* 共通: 画像アップロード */}
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1.5">
              写真（最大5枚）
            </label>
            <input
              ref={fileInputRef}
              type="file"
              accept="image/*"
              multiple
              onChange={handleFileChange}
              className="hidden"
            />
            <div className="flex flex-wrap gap-3">
              {previewImages.map((img, index) => (
                <div key={index} className="relative w-20 h-20 rounded-lg overflow-hidden group">
                  <img src={img} alt="" className="w-full h-full object-cover object-top" />
                  <button
                    onClick={() => removeImage(index)}
                    className="absolute inset-0 bg-black/50 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center cursor-pointer"
                  >
                    <i className="ri-delete-bin-line text-white text-lg"></i>
                  </button>
                </div>
              ))}
              {previewImages.length < 5 && (
                <button
                  onClick={handleImageSelect}
                  className="w-20 h-20 border-2 border-dashed border-gray-300 rounded-lg flex flex-col items-center justify-center hover:border-teal-500 hover:bg-teal-50 transition-colors cursor-pointer"
                >
                  <i className="ri-camera-line text-xl text-gray-400"></i>
                  <span className="text-xs text-gray-400 mt-1">追加</span>
                </button>
              )}
            </div>
          </div>
        </div>

        {/* フッター */}
        <div className="px-6 py-4 border-t border-gray-200 flex items-center justify-end gap-3">
          <button
            onClick={handleClose}
            className="px-5 py-2.5 text-sm font-medium text-gray-700 bg-gray-100 rounded-lg hover:bg-gray-200 transition-colors whitespace-nowrap cursor-pointer"
          >
            キャンセル
          </button>
          <button
            onClick={handleSubmit}
            disabled={!canSubmit() || submitting}
            className={`px-6 py-2.5 text-sm font-medium text-white rounded-lg whitespace-nowrap transition-colors cursor-pointer flex items-center gap-2 ${
              canSubmit() && !submitting
                ? 'bg-teal-500 hover:bg-teal-600'
                : 'bg-gray-300 cursor-not-allowed'
            }`}
          >
            {submitting && (
              <i className="ri-loader-4-line animate-spin"></i>
            )}
            {submitting ? '投稿中...' : '投稿する'}
          </button>
        </div>
      </div>
    </div>
  );
}
