import { useState } from 'react';
import { Link } from 'react-router-dom';
import { diaryPosts, myCars, garagePhotos, touringEvents } from '../../mocks/community';
import DiaryCard from './components/DiaryCard';
import MyCarCard from './components/MyCarCard';
import GaragePhotoCard from './components/GaragePhotoCard';
import TouringEventCard from './components/TouringEventCard';
import PostModal from './components/PostModal';
import GlobalHeader from '../../components/feature/GlobalHeader';
import GlobalFooter from '../../components/feature/GlobalFooter';
import Breadcrumb from '../../components/feature/Breadcrumb';

export default function CommunityPage() {
  const [activeTab, setActiveTab] = useState<'diary' | 'mycar' | 'garage' | 'touring'>('diary');
  const [isPostModalOpen, setIsPostModalOpen] = useState(false);
  const [toastMessage, setToastMessage] = useState('');

  const handlePostSubmit = (data: Record<string, string | string[]>) => {
    console.log('Post submitted:', data);
    setToastMessage('投稿が完了しました！');
    setTimeout(() => setToastMessage(''), 3000);
  };

  const postButtonLabels: Record<string, string> = {
    diary: '日記を書く',
    mycar: 'Myカーを登録',
    garage: '写真を投稿',
    touring: 'ツーリングを募集',
  };

  return (
    <div className="min-h-screen bg-gray-50">
      {/* 共通ヘッダー */}
      <GlobalHeader showBanner={false} showSearch={false} />

      {/* パンくずリスト */}
      <Breadcrumb items={[{ label: 'コミュニティ' }]} />

      {/* ページヘッダー＆タブ */}
      <div className="bg-white border-b">
        <div className="max-w-7xl mx-auto px-4 py-4">
          <div className="flex items-center justify-between mb-4">
            <div>
              <h1 className="text-2xl font-bold text-gray-900">コミュニティ</h1>
              <p className="text-sm text-gray-600 mt-1">みんなのカーライフをシェアしよう</p>
            </div>
            <button
              onClick={() => setIsPostModalOpen(true)}
              className="flex items-center gap-2 bg-teal-500 text-white px-5 py-2.5 rounded-lg hover:bg-teal-600 transition-colors text-sm font-medium whitespace-nowrap cursor-pointer shadow-sm"
            >
              <i className="ri-edit-line"></i>
              {postButtonLabels[activeTab]}
            </button>
          </div>

          {/* タブ */}
          <div className="flex gap-2 overflow-x-auto">
            <button
              onClick={() => setActiveTab('diary')}
              className={`px-6 py-2 rounded-full text-sm font-medium whitespace-nowrap transition-colors ${
                activeTab === 'diary'
                  ? 'bg-teal-500 text-white'
                  : 'bg-gray-100 text-gray-700 hover:bg-gray-200'
              }`}
            >
              <i className="ri-book-2-line mr-2"></i>
              みんなの日記
            </button>
            <button
              onClick={() => setActiveTab('mycar')}
              className={`px-6 py-2 rounded-full text-sm font-medium whitespace-nowrap transition-colors ${
                activeTab === 'mycar'
                  ? 'bg-teal-500 text-white'
                  : 'bg-gray-100 text-gray-700 hover:bg-gray-200'
              }`}
            >
              <i className="ri-car-line mr-2"></i>
              Myカー
            </button>
            <button
              onClick={() => setActiveTab('garage')}
              className={`px-6 py-2 rounded-full text-sm font-medium whitespace-nowrap transition-colors ${
                activeTab === 'garage'
                  ? 'bg-teal-500 text-white'
                  : 'bg-gray-100 text-gray-700 hover:bg-gray-200'
              }`}
            >
              <i className="ri-tools-line mr-2"></i>
              みんなのガレージ
            </button>
            <button
              onClick={() => setActiveTab('touring')}
              className={`px-6 py-2 rounded-full text-sm font-medium whitespace-nowrap transition-colors ${
                activeTab === 'touring'
                  ? 'bg-teal-500 text-white'
                  : 'bg-gray-100 text-gray-700 hover:bg-gray-200'
              }`}
            >
              <i className="ri-map-pin-line mr-2"></i>
              ツーリング
            </button>
          </div>
        </div>
      </div>

      {/* コンテンツ */}
      <div className="max-w-7xl mx-auto px-4 py-8">
        {/* みんなの日記 */}
        {activeTab === 'diary' && (
          <div>
            <div className="flex items-center justify-between mb-6">
              <h2 className="text-xl font-bold text-gray-900">新着日記</h2>
              <div className="flex items-center gap-3">
                <button
                  onClick={() => setIsPostModalOpen(true)}
                  className="flex items-center gap-1.5 text-sm text-teal-500 hover:text-teal-600 font-medium whitespace-nowrap cursor-pointer"
                >
                  <i className="ri-edit-line"></i>
                  日記を書く
                </button>
                <button className="text-sm text-teal-500 hover:text-teal-600 font-medium whitespace-nowrap cursor-pointer">
                  もっと見る
                  <i className="ri-arrow-right-line ml-1"></i>
                </button>
              </div>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
              {diaryPosts.map((post) => (
                <DiaryCard key={post.id} {...post} />
              ))}
            </div>
          </div>
        )}

        {/* Myカー */}
        {activeTab === 'mycar' && (
          <div>
            <div className="flex items-center justify-between mb-6">
              <h2 className="text-xl font-bold text-gray-900">新着Myカー</h2>
              <div className="flex items-center gap-3">
                <button
                  onClick={() => setIsPostModalOpen(true)}
                  className="flex items-center gap-1.5 text-sm text-teal-500 hover:text-teal-600 font-medium whitespace-nowrap cursor-pointer"
                >
                  <i className="ri-add-line"></i>
                  Myカーを登録
                </button>
                <button className="text-sm text-teal-500 hover:text-teal-600 font-medium whitespace-nowrap cursor-pointer">
                  もっと見る
                  <i className="ri-arrow-right-line ml-1"></i>
                </button>
              </div>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {myCars.map((car) => (
                <MyCarCard key={car.id} {...car} />
              ))}
            </div>
          </div>
        )}

        {/* みんなのガレージ */}
        {activeTab === 'garage' && (
          <div>
            <div className="flex items-center justify-between mb-6">
              <h2 className="text-xl font-bold text-gray-900">カスタム写真ギャラリー</h2>
              <div className="flex items-center gap-3">
                <button
                  onClick={() => setIsPostModalOpen(true)}
                  className="flex items-center gap-1.5 text-sm text-teal-500 hover:text-teal-600 font-medium whitespace-nowrap cursor-pointer"
                >
                  <i className="ri-camera-line"></i>
                  写真を投稿
                </button>
                <button className="text-sm text-teal-500 hover:text-teal-600 font-medium whitespace-nowrap cursor-pointer">
                  もっと見る
                  <i className="ri-arrow-right-line ml-1"></i>
                </button>
              </div>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {garagePhotos.map((photo) => (
                <GaragePhotoCard key={photo.id} {...photo} />
              ))}
            </div>
          </div>
        )}

        {/* ツーリング */}
        {activeTab === 'touring' && (
          <div>
            <div className="flex items-center justify-between mb-6">
              <h2 className="text-xl font-bold text-gray-900">募集中のツーリング</h2>
              <div className="flex items-center gap-3">
                <button
                  onClick={() => setIsPostModalOpen(true)}
                  className="flex items-center gap-1.5 text-sm text-teal-500 hover:text-teal-600 font-medium whitespace-nowrap cursor-pointer"
                >
                  <i className="ri-map-pin-add-line"></i>
                  ツーリングを募集
                </button>
                <button className="text-sm text-teal-500 hover:text-teal-600 font-medium whitespace-nowrap cursor-pointer">
                  もっと見る
                  <i className="ri-arrow-right-line ml-1"></i>
                </button>
              </div>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {touringEvents.map((event) => (
                <TouringEventCard key={event.id} {...event} />
              ))}
            </div>
          </div>
        )}
      </div>

      {/* 投稿モーダル */}
      <PostModal
        isOpen={isPostModalOpen}
        onClose={() => setIsPostModalOpen(false)}
        postType={activeTab}
        onSubmit={handlePostSubmit}
      />

      {/* トースト通知 */}
      {toastMessage && (
        <div className="fixed bottom-6 left-1/2 -translate-x-1/2 z-50 bg-gray-900 text-white px-6 py-3 rounded-lg shadow-lg flex items-center gap-2 animate-fade-in">
          <i className="ri-check-line text-green-400"></i>
          <span className="text-sm font-medium">{toastMessage}</span>
        </div>
      )}

      {/* フッター */}
      <GlobalFooter />
    </div>
  );
}
